/* The collection UI talks to a same-origin map generated by Python/Folium. */
"use strict";
(() => {
  const data = JSON.parse(document.getElementById("atlasData").textContent);
  const byId = new Map(data.species.map(species => [species.id, species]));
  const frame = document.getElementById("mapFrame");
  const rows = [...document.querySelectorAll(".species-row")];
  const search = document.getElementById("speciesSearch");
  const allButton = document.getElementById("allSpecies");
  const list = document.getElementById("speciesList");
  let selectedId = null;
  let basemap = "street";
  let ready = false;
  let failureTimer;

  function mapApi() {
    try { return ready ? frame.contentWindow.AtlasMap : null; } catch (_) { return null; }
  }
  function announce(message) { document.getElementById("announcer").textContent = message; }
  function renderLegend() {
    const container = document.getElementById("legendItems");
    container.replaceChildren();
    for (const species of (selectedId ? [byId.get(selectedId)] : data.species)) {
      const item = document.createElement("div");
      item.className = "legend-item";
      const swatch = document.createElement("span");
      swatch.style.backgroundColor = species.color;
      const name = document.createElement("span");
      name.textContent = species.name;
      const count = document.createElement("small");
      count.textContent = species.count;
      item.append(swatch, name, count);
      container.append(item);
    }
  }
  function selectSpecies(id) {
    selectedId = byId.has(id) ? id : null;
    const species = byId.get(selectedId);
    const count = species ? species.count : data.stats.observations;
    rows.forEach(row => {
      const active = row.dataset.species === selectedId;
      row.classList.toggle("selected", active);
      row.setAttribute("aria-pressed", String(active));
    });
    allButton.classList.toggle("selected", !selectedId);
    allButton.setAttribute("aria-pressed", String(!selectedId));
    document.getElementById("mapTitle").textContent = species ? species.name : "The field map";
    document.getElementById("mapSubtitle").textContent = species
      ? `${count} observation${count === 1 ? "" : "s"} · ${species.scientific_name || "Mt. Carmel, Bayugan City"}`
      : `All ${data.stats.species} species · ${data.stats.observations} observations`;
    document.getElementById("selectionLabel").textContent = species ? species.name : "All plant species";
    document.getElementById("selectionDot").style.background = species ? species.color : "";
    document.getElementById("clearSelection").hidden = !selectedId;
    document.getElementById("visibleCount").textContent = `${count} observation${count === 1 ? "" : "s"} on the map`;
    const query = selectedId ? `?species=${encodeURIComponent(selectedId)}` : "";
    document.getElementById("exportCsv").href = `/download/observations.csv${query}`;
    document.getElementById("exportGeojson").href = `/download/observations.geojson${query}`;
    document.getElementById("exportCsv").setAttribute("aria-label", `Download ${species ? species.name : "all observations"} as CSV`);
    document.getElementById("exportGeojson").setAttribute("aria-label", `Download ${species ? species.name : "all observations"} as GeoJSON`);
    mapApi()?.selectSpecies(selectedId);
    renderLegend();
    announce(`${species ? species.name : "All plant species"}: ${count} observations shown.`);
  }
  rows.forEach(row => row.addEventListener("click", () => selectSpecies(row.dataset.species)));
  allButton.addEventListener("click", () => selectSpecies(null));
  document.getElementById("clearSelection").addEventListener("click", () => selectSpecies(null));

  function filterList() {
    const term = search.value.toLocaleLowerCase().trim();
    let matches = 0;
    rows.forEach(row => {
      const match = `${row.dataset.name} ${row.dataset.scientific}`.toLocaleLowerCase().includes(term);
      row.hidden = !match;
      if (match) matches++;
    });
    document.getElementById("resultsCount").textContent = `${matches} SPECIES${term ? " FOUND" : ""}`;
    document.getElementById("clearSearch").hidden = !search.value;
    document.getElementById("emptySearch").hidden = matches > 0;
    list.hidden = matches === 0;
  }
  function clearSearch() { search.value = ""; filterList(); search.focus(); }
  search.addEventListener("input", filterList);
  document.getElementById("clearSearch").addEventListener("click", clearSearch);
  document.getElementById("resetSearch").addEventListener("click", clearSearch);
  document.getElementById("speciesSort").addEventListener("change", event => {
    const sorted = [...rows].sort((a, b) => event.target.value === "count"
      ? Number(b.dataset.count) - Number(a.dataset.count) || a.dataset.name.localeCompare(b.dataset.name)
      : a.dataset.name.localeCompare(b.dataset.name));
    sorted.forEach(row => list.append(row));
  });
  document.querySelectorAll("[data-basemap]").forEach(button => button.addEventListener("click", () => {
    basemap = button.dataset.basemap;
    document.querySelectorAll("[data-basemap]").forEach(tab => {
      const active = tab === button;
      tab.classList.toggle("active", active);
      tab.setAttribute("aria-pressed", String(active));
    });
    document.getElementById("tileNotice").hidden = true;
    mapApi()?.setBasemap(basemap);
  }));
  document.getElementById("fitMap").addEventListener("click", () => mapApi()?.fitSelection());
  document.getElementById("zoomIn").addEventListener("click", () => mapApi()?.zoomIn());
  document.getElementById("zoomOut").addEventListener("click", () => mapApi()?.zoomOut());
  const panel = document.getElementById("mapPanel");
  const expandButton = document.getElementById("fullscreenMap");
  function refreshFullscreen() {
    const expanded = document.fullscreenElement === panel || panel.classList.contains("expanded");
    expandButton.setAttribute("aria-pressed", String(expanded));
    expandButton.setAttribute("aria-label", expanded ? "Exit expanded map" : "Expand map");
    expandButton.title = expanded ? "Exit expanded map" : "Expand map";
    setTimeout(() => mapApi()?.invalidateSize(), 100);
  }
  expandButton.addEventListener("click", async () => {
    if (document.fullscreenElement === panel) await document.exitFullscreen();
    else if (panel.classList.contains("expanded")) panel.classList.remove("expanded");
    else {
      try {
        if (!panel.requestFullscreen) throw new Error("Fullscreen unavailable");
        await panel.requestFullscreen();
      } catch (_) { panel.classList.add("expanded"); }
    }
    refreshFullscreen();
  });
  document.addEventListener("fullscreenchange", refreshFullscreen);
  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && panel.classList.contains("expanded")) {
      panel.classList.remove("expanded"); refreshFullscreen(); expandButton.focus();
    }
  });
  const legendToggle = document.getElementById("legendToggle");
  legendToggle.addEventListener("click", () => {
    const open = legendToggle.getAttribute("aria-expanded") !== "true";
    legendToggle.setAttribute("aria-expanded", String(open));
    document.getElementById("legendContent").hidden = !open;
  });
  const dialog = document.getElementById("aboutDialog");
  document.querySelectorAll("[data-open-about]").forEach(button => button.addEventListener("click", () => dialog.showModal()));
  document.getElementById("closeAbout").addEventListener("click", () => dialog.close());
  document.getElementById("startExploring").addEventListener("click", () => dialog.close());
  dialog.addEventListener("click", event => {
    if (event.target === dialog) {
      const rect = dialog.getBoundingClientRect();
      if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close();
    }
  });
  function mapReady() {
    ready = true;
    clearTimeout(failureTimer);
    document.getElementById("mapStage").classList.remove("has-popup");
    document.getElementById("mapLoading").hidden = true;
    document.getElementById("mapFailure").hidden = true;
    mapApi()?.setBasemap(basemap);
    if (selectedId) mapApi()?.selectSpecies(selectedId);
  }
  window.addEventListener("message", event => {
    if (event.source !== frame.contentWindow || event.origin !== window.location.origin || !event.data) return;
    if (event.data.type === "atlas:ready") mapReady();
    if (["atlas:move", "atlas:cursor"].includes(event.data.type)) {
      const { latitude, longitude } = event.data;
      if (Number.isFinite(latitude) && Number.isFinite(longitude))
        document.getElementById("mapCoordinates").textContent = `${latitude.toFixed(5)}° N  ${longitude.toFixed(5)}° E`;
    }
    if (event.data.type === "atlas:tile-error") document.getElementById("tileNotice").hidden = false;
    if (event.data.type === "atlas:popup") {
      document.getElementById("mapTip").hidden = true;
      document.getElementById("mapStage").classList.toggle("has-popup", Boolean(event.data.open));
    }
  });
  frame.addEventListener("load", () => {
    try { if (frame.contentWindow.AtlasMap) mapReady(); } catch (_) { /* Error page stays in the iframe. */ }
  });
  function awaitMap() {
    clearTimeout(failureTimer);
    failureTimer = setTimeout(() => {
      if (!ready) {
        document.getElementById("mapLoading").hidden = true;
        document.getElementById("mapFailure").hidden = false;
      }
    }, 20000);
  }
  document.getElementById("retryMap").addEventListener("click", () => {
    ready = false;
    document.getElementById("mapFailure").hidden = true;
    document.getElementById("mapLoading").hidden = false;
    frame.src = "/map";
    awaitMap();
  });
  renderLegend();
  awaitMap();
  // An iframe can finish before the parent defer script attaches its listener.
  try { if (frame.contentWindow.AtlasMap) mapReady(); } catch (_) { /* Wait for ready. */ }
})();
